        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[] arr = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            arr[i] = (long) in.nval;
        }
        long[] res = optimizedBubbleSort(arr);
        StringBuilder sb = new StringBuilder();
        sb.append(res[0]).append("\n").append(res[1]).append("\n");
        for (int i = 0; i < n; i++) sb.append(arr[i]).append(i + 1 < n ? " " : "\n");
